def lower_bound(a, x):
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

import random

import pytest

from search import lower_bound


def test_all_elements_smaller_than_x():
    assert lower_bound([1, 3, 5], 10) == 3


def test_empty_list():
    assert lower_bound([], 1) == 0


def test_single_element_larger():
    assert lower_bound([2], 3) == 1


def test_insertion_points():
    assert lower_bound([1, 3, 5], 0) == 0
    assert lower_bound([1, 3, 5], 1) == 0
    assert lower_bound([1, 3, 5], 2) == 1
    assert lower_bound([1, 3, 5], 3) == 1
    assert lower_bound([1, 3, 5], 4) == 2
    assert lower_bound([1, 3, 5], 5) == 2
    assert lower_bound([1, 3, 5], 6) == 3


def test_duplicates_first_occurrence():
    a = [1, 2, 2, 2, 3]
    assert lower_bound(a, 2) == 1
    assert lower_bound(a, 0) == 0
    assert lower_bound(a, 4) == 5


def _linear_lower_bound(a, x):
    for i, v in enumerate(a):
        if v >= x:
            return i
    return len(a)


def test_brute_force_against_linear_scan():
    rng = random.Random(12345)
    for _ in range(200):
        n = rng.randrange(0, 20)
        a = sorted(rng.randrange(-50, 50) for _ in range(n))
        x = rng.randrange(-60, 60)
        assert (
            lower_bound(a, x) == _linear_lower_bound(a, x)
        ), f"lower_bound({a}, {x}) mismatch"

